// ---- SET BONUS (counts worn Memorial pieces; applied ONCE here) ----
// EQI_COMPOUND_ON == this item -> the block only runs from the armor's
// own script, so wearing several pieces never stacks the bonus.
if (getequipid(EQI_COMPOUND_ON) == 40700) {
    .@set = 0;
    if (getequipid(EQI_ARMOR)   == 40700) .@set++;
    if (getequipid(EQI_GARMENT) == 40701) .@set++;
    if (getequipid(EQI_SHOES)   == 40702) .@set++;
    if (getequipid(EQI_ACC_R)   == 40703 || getequipid(EQI_ACC_L) == 40703) .@set++;
    if (getequipid(EQI_HEAD_MID) == 40704) .@set++;
    if (.@set >= 3) {                            // 3-piece set bonus [TUNABLE]
        bonus bMaxHPrate,5;
        bonus bMaxSPrate,5;
        bonus2 bAddClass,Class_All,3;            // +3% physical dmg to all
        bonus2 bMagicAddClass,Class_All,3;       // +3% magic dmg to all (caster parity)
        bonus bAllStats,2;
    }
    if (.@set >= 5) {                            // full 5-piece bonus [TUNABLE]
        bonus bMaxHPrate,5;
        bonus bMaxSPrate,5;
        bonus2 bAddClass,Class_All,3;
        bonus2 bMagicAddClass,Class_All,3;
        bonus bAllStats,2;
    }
}

